import{_ as a,a0 as i,w as d,s as u,ao as l,I as p,x as e,a1 as o,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧-改变登陆窗口背景 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧-改变登陆窗口背景 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧-改变登陆窗口背景 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧-改变登陆窗口背景 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips–Change The Logon Screen Background","title":"每日Ubuntu小技巧-改变登陆窗口背景","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips–Change The Logon Screen Background.md","filePath":"[post].md"}'),s={name:"201311/Daily Ubuntu Tips–Change The Logon Screen Background.md"};function g(m,t,b,T,c,f){const n=i("Link");return d(),u("div",null,[t[11]||(t[11]=l(`<h1 id="每日ubuntu小技巧-改变登陆窗口背景" tabindex="-1">每日Ubuntu小技巧-改变登陆窗口背景 <a class="header-anchor" href="#每日ubuntu小技巧-改变登陆窗口背景" aria-label="Permalink to “每日Ubuntu小技巧-改变登陆窗口背景”">​</a></h1><p>本文为你提供了一个简单的小技巧，告诉你如何用你自己图片来替换登陆窗口的背景。Ubuntu的登陆窗口挺不错的，可能比大多数发行版的都要好，但是如果你想要使用一张你自己的图片，比如一张可以让你回忆起某个特定的地方或事情的图片，你就可以按照下面的步骤来更换上它。</p><p>有许多方法可以做到这一点，这篇博文介绍的只是其中一种。下面介绍的方法可以使用dconf-editor和lightdm用户身份来完成这样的效果。简单来说就是，切换到root用户，给予lightdm用户访问x-server的权限。然后使用lightdm用户身份，运行dconf-editor，然后做出修改。</p><p>在设置完自定义图片并且重启后，每次启动电脑时你就应该能看到你设置的图片。若设置的图片是一张你非常喜欢的并且能给你带给你很多回忆的图片，那么你每次启动电脑登陆到Ubuntu时一定非常开心。</p><p>这个手册假设你已经在你的电脑上安装了dconf-editor。若没有，你可以运行以下命令来安装dconf-editor</p><pre><code>sudo apt-get install dconf-editor
</code></pre><p>下一步，选择你要作为登陆背景的图片。然后，记下图片的位置以及图片的名字，运行以下命令切换到root用户。</p><pre><code>sudo –i
</code></pre><p>下一步，运行以下命令给予lightdm用户访问X-server的权限。Lightdm是一个管理登陆窗口背景的服务程序，因此假如你要更换登陆窗口的背景图片，你就要修改lightdm用户。</p><pre><code>xhost +SI:localuser:lightdm
</code></pre><p>下一步，运行以下命令切换到lightdm用户</p><pre><code>su lightdm -s /bin/bash
</code></pre><p>然后，运行以下命令开启dconf-editor</p><pre><code>dconf-editor
</code></pre><p>当工具打开后，浏览到 <strong>com-&gt;canonical-&gt;unity-greeter</strong>。然后改变背景值为自定义的图盘。你可能需要勾掉draw-grid。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/logon-screen-background.png" alt=""></p><p>重启电脑，尽情享受~</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/logon-screen-background-1.png" alt=""></p><hr>`,19)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tipschange-logon-screen-background/"},{default:r(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/09/daily-ubuntu-tipschange-logon-screen-background/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[2]||(t[2]=[e("LCTT",-1)])]),_:1}),t[5]||(t[5]=e(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:r(()=>[...t[3]||(t[3]=[e("Linux中国",-1)])]),_:1}),t[6]||(t[6]=e(" 荣誉推出",-1))]),p("p",null,[t[9]||(t[9]=e("译者：",-1)),o(n,{href:"https://github.com/Linux-pdz"},{default:r(()=>[...t[7]||(t[7]=[e("Linux-pdz",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),o(n,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...t[8]||(t[8]=[e("Caroline",-1)])]),_:1})])])}const k=a(s,[["render",g]]);export{w as __pageData,k as default};
